#dgsTalkPopup .dgs-talk-box::before,
#dgsTalkPopup .dgs-talk-box::after,
#dgsTalkPopup .dgs-talk-head::before,
#dgsTalkPopup .dgs-talk-head::after,
#dgsTalkPopup .dgs-talk-kicker::before {
